#!/usr/bin/env python3
"""Compute ground truth for CSX-133_Q1."""

from __future__ import annotations

import json
from datetime import datetime
from pathlib import Path
from typing import Any


TASK_ID = "CSX-133_Q1"
EVENT_ID = "CSX-133"
TARGET_FAMILY = "window_threshold_reconstruction"
DATA_ROOT = Path("event_packages") / "standard_event_packages" / "packages" / EVENT_ID

EVENT_PATH = "metadata/event.json"
HOURLY_PATH = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_wind_rain_point_API.json"
DAILY_PATH = "data/physical_hazard/physical_hazard_002_NASA_POWER_daily_point_weather_API.json"


def load_json(base_dir: Path, relative_path: str) -> Any:
    with (base_dir / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def parse_hour(value: str) -> datetime:
    return datetime.strptime(value, "%Y-%m-%dT%H:%M")


def daily_key_to_date(value: str) -> str:
    return f"{value[:4]}-{value[4:6]}-{value[6:8]}"


def hourly_metrics(hourly: dict[str, list[Any]]) -> dict[str, Any]:
    times = [str(value) for value in hourly["time"]]
    gusts = [float(value) for value in hourly["wind_gusts_10m"]]
    rain = [float(value) for value in hourly["precipitation"]]

    peak_gust_index = max(range(len(gusts)), key=gusts.__getitem__)
    peak_rain_index = max(range(len(rain)), key=rain.__getitem__)
    peak_gust_time = times[peak_gust_index]
    peak_rain_time = times[peak_rain_index]

    daily: dict[str, dict[str, float]] = {}
    for time_value, gust_value, rain_value in zip(times, gusts, rain):
        day = time_value[:10]
        bucket = daily.setdefault(day, {"rain_mm": 0.0, "max_gust_kmh": 0.0})
        bucket["rain_mm"] += rain_value
        bucket["max_gust_kmh"] = max(bucket["max_gust_kmh"], gust_value)

    wettest_day = max(daily, key=lambda day: daily[day]["rain_mm"])
    event_rain = sum(rain)
    wettest_day_rain = daily[wettest_day]["rain_mm"]
    lag_hours = (parse_hour(peak_rain_time) - parse_hour(peak_gust_time)).total_seconds() / 3600

    return {
        "peak_gust_kmh": round(gusts[peak_gust_index], 1),
        "peak_gust_time": peak_gust_time,
        "peak_gust_date": peak_gust_time[:10],
        "peak_hourly_rain_mm": round(rain[peak_rain_index], 1),
        "peak_hourly_rain_time": peak_rain_time,
        "peak_hourly_rain_date": peak_rain_time[:10],
        "gust_to_rain_lag_h": round(lag_hours, 1),
        "event_rain_mm": round(event_rain, 1),
        "wettest_day": wettest_day,
        "wettest_day_rain_mm": round(wettest_day_rain, 1),
        "wettest_day_share": round(wettest_day_rain / event_rain, 3),
        "wettest_day_share_pct": round(100 * wettest_day_rain / event_rain, 1),
        "daily_rain_mm": {
            day: round(values["rain_mm"], 1)
            for day, values in sorted(daily.items())
        },
        "daily_max_gust_kmh": {
            day: round(values["max_gust_kmh"], 1)
            for day, values in sorted(daily.items())
        },
    }


def daily_metrics(daily_data: dict[str, Any]) -> dict[str, Any]:
    params = daily_data["properties"]["parameter"]
    rain = {str(day): float(value) for day, value in params["PRECTOTCORR"].items()}
    wind = {str(day): float(value) for day, value in params["WS10M"].items()}
    peak_rain_day_raw = max(rain, key=rain.get)
    peak_wind_day_raw = max(wind, key=wind.get)
    return {
        "peak_daily_rain_day": daily_key_to_date(peak_rain_day_raw),
        "peak_daily_rain_mm": round(rain[peak_rain_day_raw], 2),
        "peak_daily_wind_day": daily_key_to_date(peak_wind_day_raw),
        "peak_daily_wind_m_s": round(wind[peak_wind_day_raw], 2),
    }


def build_gt() -> dict[str, Any]:
    task_dir = Path(__file__).resolve().parent
    workspace_root = task_dir.parents[2]
    package_dir = workspace_root / DATA_ROOT

    event = load_json(package_dir, EVENT_PATH)
    hourly = load_json(package_dir, HOURLY_PATH)
    daily = load_json(package_dir, DAILY_PATH)

    hourly_values = hourly_metrics(hourly["hourly"])
    daily_values = daily_metrics(daily)

    rule_flags = {
        "same_day": hourly_values["peak_gust_date"] == hourly_values["wettest_day"],
        "lag_le_2h": abs(hourly_values["gust_to_rain_lag_h"]) <= 2.0,
        "share_ge_0_60": hourly_values["wettest_day_share"] >= 0.60,
        "daily_cross_check": (
            daily_values["peak_daily_rain_day"] == hourly_values["wettest_day"]
            and daily_values["peak_daily_wind_day"] == hourly_values["wettest_day"]
        ),
    }
    answer = "same_day_wind_rain_peak" if all(rule_flags.values()) else "not_same_day_wind_rain_peak"

    primary_gt = {
        "answer": answer,
        "peak_day": hourly_values["wettest_day"],
        "metrics": {
            "peak_gust_kmh": hourly_values["peak_gust_kmh"],
            "peak_hourly_rain_mm": hourly_values["peak_hourly_rain_mm"],
            "event_rain_mm": hourly_values["event_rain_mm"],
            "wettest_day_rain_mm": hourly_values["wettest_day_rain_mm"],
            "wettest_day_share": hourly_values["wettest_day_share"],
            "gust_to_rain_lag_h": hourly_values["gust_to_rain_lag_h"],
        },
        "rule_flags": rule_flags,
        "computed_sentence": "The 7 September peak gust and rainfall maximum satisfy the same-day, 2-hour lag, 60% rainfall-share, and daily cross-check tests.",
    }

    required_metrics = [
        {"name": "peak_gust_kmh", "target": hourly_values["peak_gust_kmh"], "tolerance": 0.2, "unit": "km/h"},
        {
            "name": "peak_hourly_rain_mm",
            "target": hourly_values["peak_hourly_rain_mm"],
            "tolerance": 0.2,
            "unit": "mm",
        },
        {"name": "event_rain_mm", "target": hourly_values["event_rain_mm"], "tolerance": 0.5, "unit": "mm"},
        {
            "name": "wettest_day_rain_mm",
            "target": hourly_values["wettest_day_rain_mm"],
            "tolerance": 0.5,
            "unit": "mm",
        },
        {
            "name": "wettest_day_share",
            "target": hourly_values["wettest_day_share"],
            "tolerance": 0.01,
            "unit": "fraction",
        },
        {
            "name": "gust_to_rain_lag_h",
            "target": hourly_values["gust_to_rain_lag_h"],
            "tolerance": 0.1,
            "unit": "hours",
        },
    ]

    rubric_criteria = [
        {
            "name": "Final peak-window label",
            "points": 4,
            "description": "Returns same_day_wind_rain_peak with peak day 2024-09-07.",
            "partial_credit": "Award 2 points for the correct date with an imprecise label; award 1 point for noting strong wind and rain without applying the rule.",
        },
        {
            "name": "Hourly peak extraction",
            "points": 4,
            "description": "Reports the 116.6 km/h peak gust at 2024-09-07T12:00 and 17.8 mm peak hourly rain at 2024-09-07T13:00.",
            "partial_credit": "Award 2-3 points for one exact peak plus the correct date; award 1 point for approximate peak values without times.",
        },
        {
            "name": "Rainfall aggregation and share",
            "points": 4,
            "description": "Computes 165.3 mm event rainfall, 119.0 mm wettest-day rainfall, and wettest-day share 0.72 or 72.0%.",
            "partial_credit": "Award 2-3 points for correct accumulation values with a missing or slightly rounded share; award 1 point for only naming the wettest day.",
        },
        {
            "name": "Lag and rule flags",
            "points": 3,
            "description": "Computes a +1.0 hour gust-to-rain lag and marks same_day, lag_le_2h, and share_ge_0_60 as true.",
            "partial_credit": "Award 1-2 points for correct flags with a missing signed lag or minor threshold wording error.",
        },
        {
            "name": "Daily cross-check",
            "points": 2,
            "description": "Uses the daily precipitation maximum of 118.6 mm/day and daily 10 m wind maximum of 11.81 m/s, both on 2024-09-07.",
            "partial_credit": "Award 1 point for recognizing daily agreement but omitting one value.",
        },
        {
            "name": "Structured answer discipline",
            "points": 3,
            "description": "Provides concise JSON with the requested fields and avoids unrequested casualty, housing, mapped-damage, or broad narrative additions.",
            "partial_credit": "Award 1-2 points for correct computations with minor JSON or verbosity problems.",
        },
    ]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": TARGET_FAMILY,
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event": {
                "name": event["event_name"],
                "region": "South China Sea, Hainan, southern China, and northern Viet Nam",
                "window": {"start": "2024-09-01", "end": "2024-09-07"},
            },
            "hourly_values": hourly_values,
            "daily_values": daily_values,
            "decision_rule": {
                "label_if_all_true": "same_day_wind_rain_peak",
                "timestamp_basis": "package hourly timestamp day for hourly aggregation; daily product date for daily cross-check",
                "lag_threshold_h": 2.0,
                "wettest_day_share_threshold": 0.60,
                "flags": rule_flags,
            },
            "required_metrics": required_metrics,
        },
        "rubric": {
            "total_points": 20,
            "criteria": rubric_criteria,
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                EVENT_PATH,
                HOURLY_PATH,
                DAILY_PATH,
            ],
        },
    }


def main() -> None:
    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    with output_path.open("w", encoding="utf-8") as handle:
        json.dump(build_gt(), handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
